SourceCode.Declaration:
/// <summary>
/// Base data contract class for Azure transports
/// </summary>
[DataContract]
class OMGDataContract_Azure extends OMGDataContract
{
    KeyVaultCertificateRef      keyVaultCertificateRef;
    OMGContractDataAreaId       contractDataAreaId;   // DataAreaId where the parameters belongs
    OMGCodePage                 codePage    = '1252';
    OMGBase64Encode             base64Encode;

}

Method.Source:
[DataMember, OMGKeyVaultCertficateReffAttribue, SysOperationDisplayOrderAttribute('1')]
public KeyVaultCertificateRef parmKeyVaultCertificateRef(KeyVaultCertificateRef _keyVaultCertificateRef = keyVaultCertificateRef)
{
    keyVaultCertificateRef = _keyVaultCertificateRef;
    return keyVaultCertificateRef;
}

[DataMember, OMGContractDataAreaIdAttribue, SysOperationDisplayOrderAttribute('2')]
public OMGContractDataAreaId parmContractDataAreaId(OMGContractDataAreaId _contractDataAreaId = contractDataAreaId)
{
    contractDataAreaId = _contractDataAreaId;
    return contractDataAreaId;
}

[DataMember, SysOperationDisplayOrderAttribute('6')]
public OMGCodePage parmCodePage(OMGCodePage _codePage = codePage)
{
    codePage = _codePage;
    return codePage;
}

[DataMember, SysOperationDisplayOrderAttribute('7')]
public OMGBase64Encode parmBase64Encode(OMGBase64Encode _base64Encode = base64Encode)
{
    base64Encode = _base64Encode;
    return base64Encode;
}
